#ifndef USCOPE_DRIVER_VERSION_H
#define USCOPE_DRIVER_VERSION_H
#include <string>

// Stable declaration header: the actual version strings are generated by
// scripts/update_version.py into a translation unit in the build directory
// (driver_version.cpp). Keeping this header content-stable means regenerating
// the version never forces a recompilation of the translation units that
// include it.
extern const std::string uscope_driver_versions;
extern const std::string uscope_toolchain_versions;
#endif